import { UserRepository } from '../repositories/user-repository.js';

export function listActiveUsers(callback) {
  new UserRepository().findActive().then(
    (users) => callback(null, users),
    (err) => callback(err),
  );
}

export function findUser(id, callback) {
  new UserRepository().findById(id).then(
    (user) => callback(null, user),
    (err) => callback(err),
  );
}

export function softDeleteUser(id, when, callback) {
  new UserRepository().softDelete(id, when).then(
    (user) => callback(null, user),
    (err) => callback(err),
  );
}

import { OrderRepository } from '../repositories/order-repository.js';
import { UserRepository } from '../repositories/user-repository.js';

export function listOrdersForUser(userId, callback) {
  new OrderRepository().findByUser(userId).then(
    (orders) => callback(null, orders),
    (err) => callback(err),
  );
}

export function totalPaidCents(callback) {
  Promise.all([new UserRepository().findActive(), new OrderRepository().findPaid()])
    .then(([users, orders]) => {
      const activeIds = new Set(users.map((u) => u.id));
      const paid = orders.filter((o) => activeIds.has(o.user_id));
      callback(null, paid.reduce((sum, o) => sum + o.total_cents, 0));
    })
    .catch((err) => callback(err));
}

